*******************************************************************************
* vramrate.asm -- how fast can a 6809 put bytes into VRAM on this card?
*
*   sh software/demo/bench/run-vramrate.sh
*
* GENERATED by bench/mkvramrate.py -- the unrolled blocks are hundreds of
* literal instructions.  EDIT THE GENERATOR, not this file.
*
* docs/nitros9-hardware-improvements.md quotes VidCore at "~10 us a byte in
* masked chunks", and EVERY H-item's cost is denominated in it.  This measures
* that loop and its alternatives on the same machine, the same card and the
* same masking discipline (nitros9-av-plan.md 3.4: /IRQ open between chunks),
* so the only variable is how the inner loop is written.
*
* Each phase moves 130,560 bytes and brackets itself with a write to the
* progress port ($FF2F), which machine.c timestamps; tools/vramrate.py
* subtracts and divides.  Phases 1, 3 and 5 are vidcore.asm's Strm verbatim.
*
*   $A1 PUT  VDATA  Strm, chunk 24        $A5 GET  VDATA  Strm, chunk 24
*   $A2 PUT  VDATA  unrolled, DP, chunk 96  $A6 GET  VDATA  unrolled, DP, chunk 96
*   $A3 FILL VDATA  Strm, chunk 24        $A7 FILL WINDOW STD <dp, two bytes an instruction
*   $A4 FILL VDATA  unrolled, DP, chunk 96  $A8 PUT  WINDOW PULU + STD/STX/STY <dp
*   $A0 the timed phases end (the self-check runs after it)
*   $AF done
*******************************************************************************

MAPHI   EQU     $FF90
MAPLO   EQU     $FFA0
SIMPORT EQU     $FF2F
VBASE   EQU     $FF60
VCTRL   EQU     $FF60
WFG     EQU     $FF66
WBG     EQU     $FF67
WPTR0   EQU     $FF68
WPTR1   EQU     $FF69
WPTR2   EQU     $FF6A
WADV    EQU     $FF74
VDATA   EQU     $FF75
O_VDATA EQU     VDATA-VBASE     $15 -- vidcore.asm addresses it as VR.VDATA,u

VRAMWIN EQU     $2000           logical block 1: an 8 KB window on the ring
VRDP    EQU     $20             DP that puts direct addressing in that window
SRCBUF  EQU     $4000           16 KB of SIMM: the source and the sink
IRQMASK EQU     $10

SCnt    EQU     $C000           vidcore.asm's VG.SCnt and friends
SFill   EQU     $C002
SByte   EQU     $C003
PtrN    EQU     $C004
PtrGen  EQU     $C006
PtrSeen EQU     $C007
Base    EQU     $C008
total   EQU     $C00A
fillw   EQU     $C00C
cmph    EQU     $C00E           the compare's outer count -- RAM, not ROM

        ORG     $8000
        FCC     "6309"
        JMP     start

        SETDP   $FF
start   orcc    #$50
        lds     #$E000
        lda     #$FF
        tfr     a,dp

* --- block 1 is the VRAM window (boot.asm section 2: physical A20:A19 = 01)
        clr     MAPHI+1
        lda     #$40
        sta     MAPLO+1

* --- the card: display off, WMODE 00 direct, no IRQ.  Nothing is displayed,
*     so no phase depends on what the frame shows.
        clr     VCTRL
        clr     WADV
        clr     WFG
        clr     WBG
        ldd     #VBASE
        std     Base
        clr     PtrGen
        clr     PtrSeen
        ldd     #$5A5A
        std     fillw

* --- a source pattern, so a wrong loop is visible as well as slow
        ldx     #SRCBUF
        clrb
srcfl   stb     ,x+
        incb
        cmpx    #SRCBUF+16384
        bne     srcfl
        lbra    run

setwp   clr     WPTR0
        clr     WPTR1
        clr     WPTR2
        rts

mark    sta     SIMPORT
        rts

* --- Strm: vidcore.asm's chunked streamer, verbatim except that the statics
*     are absolute.  VcWait can never fire here: nothing else touches WPTR.
*     SFill 0 = put (X -> VDATA), 1 = fill (SByte), 2 = get (VDATA -> X)
Strm    pshs    cc,u
        ldu     Base
sch     orcc    #IRQMASK
        lda     PtrGen
        cmpa    PtrSeen
        beq     sgo
sgo     ldd     SCnt
        cmpd    #24
        bls     sc1
        ldb     #24
sc1     pshs    b
        lda     SFill
        beq     sp
        cmpa    #2
        bne     sf
sg      lda     O_VDATA,u
        sta     ,x+
        decb
        bne     sg
        bra     scd
sp      lda     ,x+
        sta     O_VDATA,u
        decb
        bne     sp
        bra     scd
sf      lda     SByte
sfl     sta     O_VDATA,u
        decb
        bne     sfl
scd     clra
        ldb     ,s
        addd    PtrN
        std     PtrN
        clra
        puls    b
        pshs    d
        ldd     SCnt
        subd    ,s++
        std     SCnt
        beq     send
        lda     ,s
        bita    #IRQMASK
        bne     sch
        andcc   #$EF
        bra     sch
send    puls    cc,u,pc

