        sta     total
pa8l    ldd     #8160
        std     SCnt
        ldu     #SRCBUF
        lbsr    wput
        dec     total
        bne     pa8l
        rts

*------------------------------------------------------------------ the check
* A loop that is fast and wrong is worth nothing, and the GET phases overwrite
* the source, so correctness is asserted here rather than inferred from a dump.
* Each PUT form fills ring row 0 (wstep wraps within 1024 bytes) and vidcore's
* own Strm GET reads it back.  $AE = every form agreed, $EE = one did not.
CMPBUF  EQU     $6000

* mkpat - B = seed; CHECKSZ bytes of seed, seed+1, ...  A different seed per
* form, so a form that writes short fails against the previous form's bytes
* instead of matching them.
mkpat   ldx     #SRCBUF
mkpl    stb     ,x+
        incb
        cmpx    #SRCBUF+960
        bne     mkpl
        rts

* rdback - WPTR := 0, then Strm GET 1024 bytes into CMPBUF, and compare
rdback  lbsr    setwp
        lda     #2
        sta     SFill
        ldd     #960
        std     SCnt
        ldx     #CMPBUF
        lbsr    Strm
        ldx     #SRCBUF
        ldy     #CMPBUF
        ldd     #960
        std     cmph
cmpl    lda     ,x+
        cmpa    ,y+
        bne     cmpbad
        ldd     cmph
        subd    #1
        std     cmph
        bne     cmpl
        andcc   #$FE            carry clear: they agree
        rts
cmpbad  orcc    #$01
        rts

verify
* --- Strm, vidcore verbatim
        clrb
        lbsr    mkpat
        lbsr    setwp
        clr     SFill
        ldd     #960
        std     SCnt
        ldx     #SRCBUF
        lbsr    Strm
        lbsr    rdback
        bcs     vbad
        lda     #$AB
        lbsr    mark

* --- the unrolled VDATA form
        ldb     #$55
        lbsr    mkpat
        lbsr    setwp
        ldd     #960
        std     SCnt
        ldx     #SRCBUF
        lbsr    fput
        lbsr    rdback
        bcs     vbad
        lda     #$AC
        lbsr    mark

* --- PULU + three 16-bit stores, through the window
        ldb     #$AA
        lbsr    mkpat
        lbsr    setwp
        ldd     #960
        std     SCnt
        ldu     #SRCBUF
        lbsr    wput
        lbsr    rdback
        bcs     vbad

        lda     #$AE
        lbsr    mark
        rts
vbad    lda     #$EE
        lbsr    mark
        rts

run     lbsr    pa1
        lbsr    pa2
        lbsr    pa3
        lbsr    pa4
        lbsr    pa5
        lbsr    pa6
        lbsr    pa7
        lbsr    pa8
        lda     #$A0            the last phase ends HERE, not at $AF
        lbsr    mark
        lbsr    verify
        lda     #$AF
        lbsr    mark
done    bra     done

        END
